/*
  A pose is where one piece is. A formation is a pose for every piece plus how
  the whole stack is turned and placed. The scene at rest on a beat is one
  formation; moving between beats is a blend of two.
*/

export type Vec3 = [number, number, number];

export type Pose = {
  position: Vec3;
  /** Euler angles in radians, applied in X, Y, Z order. */
  rotation: Vec3;
  /** Width and height. */
  size: [number, number];
};

export type Formation = {
  pieces: Pose[];
  /** How the whole stack is turned, about X then Y, in radians. */
  turn: [number, number];
  /**
   * Where the stack sits on a wide screen, as a share of half the screen:
   * 0.5 across is halfway from the middle to the right edge. Narrow screens
   * centre it.
   */
  anchor: [number, number];
  /** How much the pieces drift while idle, 0 to 1. */
  drift: number;
  /** How wide the formation is, so the camera can stand back far enough. */
  span: number;
  /** How tall it is, for the same reason. */
  rise: number;
  /** The closest the camera comes to the formation. */
  near: number;
  /**
   * How the view changes while the beat is scrolled through: the turn about
   * X, the turn about Y, and the distance, each centred on the formation's
   * own.
   */
  sway: Vec3;
  /** The height of the floor under the formation. */
  floor: number;
  /**
   * 1 when the formation stands over the caption's column on a wide screen,
   * and not beside the caption, so that it has to be fitted above the text
   * on a screen shorter than the one it was framed on. See camera.ts.
   */
  over: number;
};

export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

/** 0 below `a`, 1 above `b`, and a smooth S-curve in between. */
export function smoothstep(x: number, a: number, b: number): number {
  if (a === b) return x < a ? 0 : 1;
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

const clamp01 = (x: number): number => Math.min(1, Math.max(0, x));

/** The share of a move over which the pieces set off, one after another. */
export const SPREAD = 0.45;

/**
 * One piece's own progress through a move that is `t` of the way along. The
 * first piece sets off at once and the last when `spread` of the move has
 * gone; each then takes the time that is left. With no spread they move as
 * one.
 */
export function stagger(t: number, i: number, count: number, spread: number): number {
  if (!(spread > 0) || count <= 1) return clamp01(t);
  const share = Math.min(spread, 0.95);
  const start = (share * i) / (count - 1);
  return clamp01((t - start) / (1 - share));
}

/** A formation with every piece at the origin, to be written into. */
export function blankFormation(count: number): Formation {
  return {
    pieces: Array.from(
      { length: count },
      (): Pose => ({ position: [0, 0, 0], rotation: [0, 0, 0], size: [1, 1] }),
    ),
    turn: [0, 0],
    anchor: [0, 0],
    drift: 0,
    span: 0,
    rise: 0,
    near: 0,
    sway: [0, 0, 0],
    floor: 0,
    over: 0,
  };
}

/**
 * Writes the blend of `a` and `b` into `out` and returns it. It allocates
 * nothing, so it can run every frame. `a` and `b` must have at least as many
 * pieces as `out`.
 *
 * `each`, when given, is every piece's own progress, so the pieces can move
 * one after another. What belongs to the whole stack always moves by `t`.
 */
export function mixFormation(
  out: Formation,
  a: Formation,
  b: Formation,
  t: number,
  each?: ArrayLike<number>,
): Formation {
  for (let i = 0; i < out.pieces.length; i++) {
    const piece = out.pieces[i];
    const from = a.pieces[i];
    const to = b.pieces[i];
    const own = each ? each[i] : t;
    for (let k = 0; k < 3; k++) {
      piece.position[k] = lerp(from.position[k], to.position[k], own);
      piece.rotation[k] = lerp(from.rotation[k], to.rotation[k], own);
    }
    piece.size[0] = lerp(from.size[0], to.size[0], own);
    piece.size[1] = lerp(from.size[1], to.size[1], own);
  }
  out.turn[0] = lerp(a.turn[0], b.turn[0], t);
  out.turn[1] = lerp(a.turn[1], b.turn[1], t);
  out.anchor[0] = lerp(a.anchor[0], b.anchor[0], t);
  out.anchor[1] = lerp(a.anchor[1], b.anchor[1], t);
  out.drift = lerp(a.drift, b.drift, t);
  out.span = lerp(a.span, b.span, t);
  out.rise = lerp(a.rise, b.rise, t);
  out.near = lerp(a.near, b.near, t);
  for (let k = 0; k < 3; k++) out.sway[k] = lerp(a.sway[k], b.sway[k], t);
  out.floor = lerp(a.floor, b.floor, t);
  out.over = lerp(a.over, b.over, t);
  return out;
}

/**
 * How far the view has swung from where the formations put it: about X,
 * about Y, and in distance. `dwell` is how far through its rest `a` is; `b`
 * has not begun its own.
 */
export function swing(
  out: Vec3,
  a: Formation,
  b: Formation,
  t: number,
  dwell: number,
): Vec3 {
  for (let k = 0; k < 3; k++) {
    out[k] = lerp(a.sway[k] * (dwell - 0.5), b.sway[k] * -0.5, t);
  }
  return out;
}

/** A beat may keep moving while it rests, driven only by its scroll dwell. */
export type BeatFormation = { rest: Formation; within?: Formation };

/** Writes a beat's current resting pose without changing its source data. */
export function atRest(out: Formation, beat: BeatFormation, dwell: number): Formation {
  const progress = Number.isFinite(dwell) ? Math.min(1, Math.max(0, dwell)) : 0;
  return mixFormation(out, beat.rest, beat.within ?? beat.rest, progress);
}
/*
  Framing: how far back the camera stands, and how high the scene sits.

  On a wide screen the caption is at the lower left and each formation is
  anchored off centre, so it is framed in the room that leaves. On a narrow one the
  caption takes the lower part of the screen, by an amount that differs from
  beat to beat and language to language, so the scene is fitted into the band
  that is left between the site header and the caption.
*/

/** What the page shell measures for the scene, in pixels. */
export type Stage = {
  viewport: number;
  /** Height of what is pinned to the top of the screen: the story's own bar. */
  header: number;
  /** Height of each beat's caption when it is pinned, in beat order. */
  captions: number[];
};

/** Room left around a formation, as a share of its size. */
const MARGIN = 1.15;

/** No band or room is ever treated as thinner than this share of the screen. */
const THINNEST = 0.15;

/**
 * How far back the camera must stand for a formation `span` units wide and
 * `rise` units tall to fit, and never closer than `nearest`. `shareX` and
 * `shareY` are how much of the screen's width and height the formation has
 * to itself: 1 when it is centred and nothing covers it.
 */
export function cameraDistance(
  span: number,
  rise: number,
  aspect: number,
  shareX: number,
  shareY: number,
  fovDegrees: number,
  nearest: number,
): number {
  if (!(aspect > 0)) return nearest;
  const heightPerUnitOfDistance = 2 * Math.tan((fovDegrees * Math.PI) / 360);
  const forWidth =
    (span * MARGIN) / (heightPerUnitOfDistance * aspect * Math.max(THINNEST, shareX));
  const forHeight =
    (rise * MARGIN) / (heightPerUnitOfDistance * Math.max(THINNEST, shareY));
  return Math.max(nearest, forWidth, forHeight);
}

/** Half the width and half the height the camera sees at a distance. */
export function viewHalf(
  distance: number,
  fovDegrees: number,
  aspect: number,
): [number, number] {
  const halfHeight = distance * Math.tan((fovDegrees * Math.PI) / 360);
  return [halfHeight * aspect, halfHeight];
}

/**
 * The share of the screen a formation has to itself when it is anchored off
 * centre by `anchor`, a share of half the screen.
 */
export function roomBeside(anchor: number): number {
  return Math.max(THINNEST, 1 - Math.abs(anchor));
}

/** The height of screen the framing on a wide screen was tuned on, in pixels. */
export const TUNED_HEIGHT = 900;

/** A formation fitted to less room than it was framed for is never drawn smaller than this. */
const SMALLEST = 0.4;

/**
 * On a wide screen most formations stand beside the caption. One that
 * stands over it instead was framed on a screen `TUNED_HEIGHT` tall. A
 * caption is as many pixels tall on a shorter screen, so it takes more of
 * it, and the formation would run into the text. This is how much smaller
 * to draw the formation there: by as much as the band between the header
 * and the caption has shrunk, as a share of the screen. It is 1 on a screen
 * that tall or taller.
 */
export function overScale(viewport: number, header: number, caption: number): number {
  const tuned = (TUNED_HEIGHT - header - caption) / TUNED_HEIGHT;
  if (!(viewport > 0) || !(tuned > 0)) return 1;
  const now = (viewport - header - caption) / viewport;
  return Math.min(1, Math.max(SMALLEST, now / tuned));
}

/**
 * And where to put it: the anchor, a share of half the screen's height,
 * that keeps the formation at the same place within that band as `anchor`
 * gave it on the screen it was framed on.
 */
export function overAnchor(
  anchor: number,
  viewport: number,
  header: number,
  caption: number,
): number {
  const tunedBand = TUNED_HEIGHT - header - caption;
  if (!(viewport > 0) || viewport >= TUNED_HEIGHT || !(tunedBand > 0)) return anchor;
  const within = (TUNED_HEIGHT * (0.5 - anchor / 2) - header) / tunedBand;
  const centre = header + within * Math.max(0, viewport - header - caption);
  return 1 - (2 * centre) / viewport;
}

/** The share of the screen's height left between the header and a caption. */
export function bandShare(viewport: number, header: number, caption: number): number {
  if (!(viewport > 0)) return 1;
  return Math.min(1, Math.max(THINNEST, (viewport - header - caption) / viewport));
}

/**
 * On a narrow screen a tall caption can leave a band thinner than the
 * thinnest the scene is framed for, and the pieces would then stand over the
 * header and the text. This is how much smaller to draw them so that they
 * keep to the band: 1 where the band is thick enough, and 0 where so little
 * is left that they should not be drawn at all.
 */
export function bandFit(viewport: number, header: number, caption: number): number {
  if (!(viewport > 0)) return 1;
  const fit = (viewport - header - caption) / viewport / THINNEST;
  if (fit >= 1) return 1;
  return fit < SMALLEST ? 0 : fit;
}

/**
 * How far above the middle of the screen the middle of that band is, as a
 * share of the screen's height. The scene is raised by this much.
 */
export function stageLift(viewport: number, header: number, caption: number): number {
  if (!(viewport > 0)) return 0;
  return (caption - header) / (2 * viewport);
}
#!/usr/bin/env node
import { spawn } from "node:child_process";
import { createWriteStream } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { createServer } from "node:net";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { checkMatrix, storyContract } from "./check-lib.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const options = Object.fromEntries(process.argv.slice(2).map(arg => {
  const [key, ...rest] = arg.replace(/^--/, "").split("=");
  return [key, rest.length ? rest.join("=") : true];
}));
const output = resolve(root, String(options.out ?? `checks/${new Date().toISOString().replace(/[:.]/g, "-")}`));
await mkdir(output, { recursive: true });
const require = createRequire(import.meta.url);
const next = require.resolve("next/dist/bin/next");
const [{ story }, { looks }] = await Promise.all([
  import(pathToFileURL(join(root, "content/story.ts")).href),
  import(pathToFileURL(join(root, "content/looks.ts")).href),
]);
const contract = storyContract(story, looks);
const probes = await readFile(join(root, "content/checks.json"), "utf8").then(JSON.parse).catch(error => {
  if (error.code === "ENOENT") return {};
  throw error;
});
const matrix = checkMatrix(contract, probes).filter(entry => !options.only || String(options.only).split(",").includes(entry.name));
if (!matrix.length) throw new Error("--only selected no checks");
const manifest = { started: new Date().toISOString(), node: process.version, scope: options.only ? "selected cases" : "full matrix", contract, probes, matrix, commands: [], results: [], complete: false };
const save = () => writeFile(join(output, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
await save();
const children = new Set();
let cancelled = false;

function stop(child, signal = "SIGTERM") {
  if (!child?.pid || child.exitCode !== null) return;
  try {
    if (process.platform === "win32") child.kill(signal);
    else process.kill(-child.pid, signal);
  }
  catch (error) { if (error.code !== "ESRCH") throw error; }
}

function launch(args, logName) {
  const log = createWriteStream(join(output, logName));
  const child = spawn(process.execPath, args, {
    cwd: root, detached: process.platform !== "win32",
    env: { ...process.env, NEXT_TELEMETRY_DISABLED: "1" }, stdio: ["ignore", "pipe", "pipe"],
  });
  children.add(child);
  manifest.commands.push([process.execPath, ...args]);
  child.stdout.on("data", chunk => log.write(chunk));
  child.stderr.on("data", chunk => log.write(chunk));
  const done = new Promise(resolveDone => {
    child.on("error", error => { log.write(`${error.stack}\n`); });
    child.on("close", (code, signal) => {
      children.delete(child);
      log.end(() => resolveDone({ code, signal }));
    });
  });
  return { child, done };
}

async function run(args, logName, timeout = 180_000) {
  const processRun = launch(args, logName);
  const timer = setTimeout(() => stop(processRun.child), timeout);
  const hardStop = setTimeout(() => stop(processRun.child, "SIGKILL"), timeout + 5000);
  try { return await processRun.done; }
  finally { clearTimeout(timer); clearTimeout(hardStop); }
}

async function freePort() {
  const server = createServer();
  await new Promise((ok, fail) => { server.once("error", fail); server.listen(0, "127.0.0.1", ok); });
  const port = server.address().port;
  await new Promise((ok, fail) => server.close(error => error ? fail(error) : ok()));
  return port;
}

async function waitForServer(url, child) {
  const deadline = Date.now() + 45_000;
  while (Date.now() < deadline) {
    if (child.exitCode !== null) throw new Error("Next.js server exited before readiness; read server.log");
    try { if ((await fetch(url, { signal: AbortSignal.timeout(1000) })).status === 200) return; }
    catch { /* The local server may still be starting. */ }
    await new Promise(ok => setTimeout(ok, 250));
  }
  throw new Error("Next.js did not return HTTP 200 within 45 seconds");
}

for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => {
  cancelled = true;
  for (const child of children) stop(child, signal);
  process.exitCode = 1;
});

let server;
try {
  if (!options["skip-build"]) {
    console.log("Building the production app");
    const result = await run([next, "build"], "build.log");
    if (result.code !== 0) throw new Error(`Production build failed (${result.code}); read build.log`);
  }
  const port = await freePort();
  const base = `http://127.0.0.1:${port}/`;
  server = launch([next, "start", "--hostname", "127.0.0.1", "--port", String(port)], "server.log");
  await waitForServer(base, server.child);
  for (const entry of matrix) {
    if (cancelled) throw new Error("Check run interrupted; remaining cases were not started");
    console.log(`Checking ${entry.name}`);
    const directory = join(output, entry.name);
    await mkdir(directory, { recursive: true });
    const reportPath = join(directory, "report.json");
    const args = [join(root, "scripts/shoot.mjs"), `--url=${base}?look=${encodeURIComponent(entry.look)}`, `--out=${directory}`, `--report=${reportPath}`, ...entry.flags];
    if (options.wait) args.push(`--wait=${options.wait}`);
    const result = await run(args, `${entry.name}.log`, 240_000);
    const report = await readFile(reportPath, "utf8").then(JSON.parse).catch(() => null);
    manifest.results.push({ name: entry.name, ...result, report: report ? `${entry.name}/report.json` : null, problems: report?.problems ?? ["No browser report; read this case's log"] });
    await save();
  }
  manifest.complete = true;
  manifest.finished = new Date().toISOString();
  await save();
  const failed = manifest.results.filter(result => result.code !== 0 || result.problems.length);
  console.log(`${matrix.length - failed.length}/${matrix.length} checks passed. Evidence: ${output}`);
  if (failed.length) process.exitCode = 1;
} catch (error) {
  manifest.error = error.stack;
  await save();
  console.error(error.message);
  process.exitCode = 1;
} finally {
  if (server) {
    stop(server.child);
    const timer = setTimeout(() => stop(server.child, "SIGKILL"), 5000);
    await server.done;
    clearTimeout(timer);
  }
  for (const child of children) stop(child);
}

